def dihedral(points,H,W):
 return {
 'id': {(r,c) for r,c in points},
 'rot90cw': {(c,H-1-r) for r,c in points},
 'rot180': {(H-1-r,W-1-c) for r,c in points},
 'rot270': {(W-1-c,r) for r,c in points},
 'flipH': {(r,W-1-c) for r,c in points},
 'flipV': {(H-1-r,c) for r,c in points},
 'transpose': {(c,r) for r,c in points},
 'anti': {(W-1-c,H-1-r) for r,c in points}}
